<template>
  <section class="mci-cdn" data-mci-ui-root aria-label="CDN监控/分析/安全">
    <header class="mci-cdn__heading"><div><h2>CDN 监控 / 分析 / 安全</h2><p>从流量来源定位资源消耗，再按域名处置异常访问。</p></div><span class="mci-cdn__tag">阿里云 CDN</span></header>
    <div v-if="initializing" class="mci-cdn__skeleton" aria-label="加载 CDN 接入信息"><i v-for="n in 4" :key="n"/></div>
    <div v-else-if="!capability.Configured" class="mci-cdn__empty"><h3>先连接当前租户的阿里云 CDN</h3><p>{{ capability.Message || '需要配置 AccessKeyId 和 AccessKeySecret。' }}</p><button @click="tab='settings'">查看接入说明</button></div>
    <div class="mci-cdn__toolbar">
      <label>加速域名<select v-model="domain" @change="changeDomain"><option value="">选择域名</option><option v-for="d in domains" :key="d.DomainName" :value="d.DomainName">{{ d.DomainName }} · {{ d.DomainStatus }}</option></select></label>
      <button :disabled="busy" @click="loadDomains">同步域名</button><button v-if="domains.length < domainCount" :disabled="busy" @click="loadMoreDomains">加载更多域名</button>
      <span class="mci-cdn__muted">凭据：{{ capability.CredentialSource?.startsWith('SaaS') ? '当前租户 SaaS（兼容）' : '当前租户私密设置' }}</span>
    </div>
    <nav class="mci-cdn__tabs" aria-label="CDN模块导航"><button v-for="item in tabs" :key="item.key" :class="{active:tab===item.key}" @click="selectTab(item.key)">{{ item.label }}</button></nav>
    <p v-if="error" role="alert" class="mci-cdn__error">{{ error }}</p>
    <div v-if="busy" class="mci-cdn__skeleton" aria-label="查询中"><i v-for="n in 3" :key="n"/></div>
    <template v-if="tab==='analysis'">
      <div class="mci-cdn__toolbar"><label>数据来源<select v-model="source" @change="analysisRows=[]"><option value="report">运营报表（历史 TOP）</option><option value="sls">SLS 日志（实时窗口）</option></select></label><label>开始时间<input v-model="start" type="datetime-local"/></label><label>结束时间<input v-model="end" type="datetime-local"/></label><button class="primary" :disabled="busy||!domain" @click="loadAnalysis">查询分析</button><button :disabled="!analysisRows.length" @click="exportRows">导出 CSV</button></div>
      <div class="mci-cdn__toolbar" v-if="source==='report'"><label>报表类型<select v-model.number="reportId"><option v-for="[id,label] in reportTypes" :key="id" :value="id">{{ label }}</option></select></label><label v-if="[13,15].includes(reportId)">地区（可选）<input v-model="area" placeholder="空值表示全部"/></label><label v-if="[21,23].includes(reportId)">地域范围<select v-model="isOverseas"><option value="0">中国内地</option><option value="1">中国内地以外</option></select></label><span v-if="reportId===17" class="mci-cdn__muted">域名排行覆盖此云账号</span><button :disabled="!domain||busy" @click="prepare('SubscribeReports')">为此域名定制全部 TOP 报表</button></div>
      <div class="mci-cdn__toolbar" v-else><label>分析维度<select v-model="dimension"><option value="ip">客户端 IP</option><option value="url">资源 URL</option><option value="referer">Referer</option><option value="ipUrl">IP × 资源</option><option value="status">HTTP 状态</option><option value="minute">分钟趋势</option></select></label><label>排序<select v-model="metric"><option value="bytes">响应流量</option><option value="requests">请求次数</option></select></label><label>精确 IP（可选）<input v-model="filterIp" placeholder="支持 IPv4 / IPv6"/></label></div>
      <div class="mci-cdn__metrics"><article><small>加速域名</small><strong>{{ domainCount }}</strong><span>云端同步结果</span></article><article><small>本次排行</small><strong>{{ analysisRows.length }}</strong><span>最多展示 500 条</span></article><article><small>数据状态</small><strong>{{ dataState }}</strong><span>{{ retrievedAt || '尚未查询' }}</span></article><article><small>自动处置</small><strong>{{ settings.AutoEnabled?'已启用':'观察保护' }}</strong><span>还需规则启用并选自动执行</span></article></div>
      <p class="mci-cdn__hint">{{ source==='report'?'运营报表须先定制，未订阅时无法补齐历史 TOP；报表窗口不能用于分钟级自动封禁。流量列保留云端原始单位，不将未知单位当作字节。':'SLS 响应流量单位为字节；IP 使用 TCP 连接地址 remote_ip。请先完成实时日志投递及字段索引，查询可能产生 SLS 费用。' }}</p>
      <ObservabilityTable :rows="analysisRows" :columns="analysisColumns" empty-text="当前窗口没有可用数据；请检查报表订阅、日志投递、时间范围和权限" search-placeholder="搜索 IP、文件或 Referer">
        <template #cell-cdnAction="{row}"><button v-if="row.remote_ip||row.ip||row.client_ip" class="mci-cdn__link" @click="analyzeIp(row)">查看文件</button><button v-if="row.remote_ip||row.ip||row.client_ip" class="mci-cdn__link danger" @click="stageBlock(row)">封禁</button></template>
      </ObservabilityTable>
      <section class="mci-cdn__panel"><header><h3>域名带宽趋势</h3><button :disabled="!domain||busy" @click="loadTrend">查询同一时间范围</button></header><svg v-if="trend.length>1" viewBox="0 0 900 140" role="img" aria-label="CDN 带宽趋势" preserveAspectRatio="none"><path :d="trendPath" fill="none" stroke="var(--obs-primary)" stroke-width="2"/></svg><p v-else class="mci-cdn__muted">查询后展示带宽趋势（bit/s）。</p><span v-if="trend.length">峰值 {{ (Math.max(...trend.map(x=>Number(x.Value)||0))/1000000).toFixed(2) }} Mbps · {{ trend.length }} 个采样点</span></section>
    </template>
    <template v-else-if="tab==='security'">
      <section class="mci-cdn__panel"><header><h3>访问控制</h3><button :disabled="!domain||busy" @click="loadSecurity">同步云端配置</button></header><div class="mci-cdn__form"><label>处置方式<select v-model="securityAction"><option value="Block">当前域名 IP 封禁</option><option value="Unblock">当前域名 IP 解封</option><option value="GlobalBlock">全账号海量 IP 封禁（需开通）</option><option value="GlobalUnblock">全账号海量 IP 解封</option><option value="RateLimit">单请求下载限速</option><option value="RemoveRateLimit">移除下载限速</option><option value="Referer">Referer 黑名单</option><option value="RemoveReferer">移除 Referer 黑名单</option></select></label><label v-if="/Block|Unblock/.test(securityAction)" class="wide">IP / CIDR<textarea v-model="ipText" rows="3" placeholder="每行一个 IP 或 CIDR，支持 IPv4 / IPv6"/></label><label v-if="securityAction.endsWith('Block')">封禁时长<select v-model.number="duration"><option :value="300">5 分钟</option><option :value="1800">30 分钟</option><option :value="3600">1 小时</option><option :value="86400">1 天</option><option :value="604800">7 天</option><option :value="0">永久</option><option :value="-1">自定义秒数</option></select></label><label v-if="duration===-1">自定义秒数<input v-model.number="customDuration" type="number" min="60" max="31536000"/></label><label v-if="securityAction==='RateLimit'">下载速度<input v-model="rate" placeholder="如 1m（MB/s），最小 100k"/></label><label v-if="securityAction==='Referer'" class="wide">Referer 域名<textarea v-model="referers" rows="3" placeholder="每行一个域名；支持 *.example.com"/></label><label v-if="securityAction==='Referer'"><input v-model="allowEmpty" type="checkbox"/>允许空 Referer</label><label class="wide">处置原因<input v-model="reason" maxlength="300"/></label><label v-if="securityAction.startsWith('Global')" class="wide mci-cdn__error"><input v-model="globalConfirm" type="checkbox"/>我确认作用于此阿里云账号下全部 CDN 域名，且已开通海量 IP 服务。</label></div><p class="mci-cdn__hint">限速单位是下载字节速度；请求次数规则通过日志检测后封禁，不能替代边缘实时 QPS 防护。定时封禁依赖后台任务，到期会仅移除本应用新增的 IP。</p><button class="primary" :disabled="busy||!domain" @click="prepare(securityAction)">预览云端变更</button></section>
      <ObservabilityTable :rows="cloudConfigs" :columns="[{key:'FunctionName',label:'云端功能'},{key:'ConfigId',label:'配置ID'},{key:'summary',label:'当前设置'}]" empty-text="尚未同步域名安全配置"/>
      <header class="mci-cdn__toolbar"><h3>处置记录与到期回收</h3><button :disabled="busy" @click="loadOperations">刷新记录</button></header><ObservabilityTable :rows="operationRows" :columns="operationColumns" empty-text="暂无 CDN 操作记录"><template #cell-status="{row}"><span :class="['Unknown','Conflict'].includes(row.Status)?'mci-cdn__error':''">{{ statuses[row.Status]||row.Status }}</span></template><template #cell-action="{row}"><button v-if="['Unknown','Running','AwaitingVerification'].includes(row.Status)" class="mci-cdn__link" @click="reconcile(row)">回读云端结果</button></template></ObservabilityTable>
    </template>
    <template v-else-if="tab==='rules'">
      <section class="mci-cdn__panel"><header><h3>{{ ruleForm.Id?'编辑规则':'新增自动阈值规则' }}</h3><button @click="resetRule">新规则</button></header><div class="mci-cdn__form"><label>规则名称<input v-model="ruleForm.Name" maxlength="100"/></label><label>模式<select v-model="ruleForm.Mode"><option value="observe">观察：记录命中</option><option value="enforce">自动执行：触发域名封禁</option></select></label><label>指标<select v-model="ruleForm.Metric"><option value="bytes">响应流量（字节）</option><option value="requests">请求次数</option></select></label><label>阈值类型<select v-model="ruleForm.ThresholdType"><option value="fixed">固定阈值</option><option value="dynamic">动态：历史 P95 × 倍数</option></select></label><label>固定阈值 / 动态下限<input v-model.number="ruleForm.Threshold" type="number" min="1"/></label><label>窗口（分钟）<input v-model.number="ruleForm.WindowMinutes" type="number" min="1" max="60"/></label><label v-if="ruleForm.ThresholdType==='dynamic'">历史窗口数量<input v-model.number="ruleForm.BaselineWindows" type="number" min="3" max="24"/></label><label v-if="ruleForm.ThresholdType==='dynamic'">P95 倍数<input v-model.number="ruleForm.Multiplier" type="number" min="2" max="100"/></label><label>连续命中次数<input v-model.number="ruleForm.Consecutive" type="number" min="1" max="10"/></label><label>封禁时长（秒）<input v-model.number="ruleForm.Duration" type="number" min="60" max="2592000"/></label><label>冷却时间（秒）<input v-model.number="ruleForm.CooldownSeconds" type="number" min="60" max="86400"/></label><label>单轮最多 IP<input v-model.number="ruleForm.MaxIps" type="number" min="1" max="20"/></label><label><input v-model="ruleForm.Enabled" type="checkbox"/>启用扫描</label></div><p class="mci-cdn__hint">只分析 SLS 每个窗口的前 100 个 IP。缺日志、流量字段缺失、窗口不完整、白名单重叠或基线样本不足时不封禁。对共享出口/NAT，请先观察实际访问。</p><button class="primary" :disabled="busy||!domain" @click="saveRule">保存规则</button></section>
      <ObservabilityTable :rows="rules" :columns="[{key:'Name',label:'规则'},{key:'modeText',label:'模式'},{key:'scanText',label:'最近扫描'},{key:'evaluation',label:'最近结果'},{key:'edit',label:'操作'}]" empty-text="暂无规则，新规则默认观察且未启用"><template #cell-edit="{row}"><button class="mci-cdn__link" @click="editRule(row)">编辑</button><button class="mci-cdn__link danger" @click="prepareRuleDelete(row)">删除</button></template></ObservabilityTable>
    </template>
    <template v-else>
      <section class="mci-cdn__panel"><h3>凭据与权限</h3><p>在「系统设置 → 安全与服务接入」添加以下私密设置，密钥只在可信后端使用：</p><code>Integration.Cdn.Aliyun.AccessKeyId<br/>Integration.Cdn.Aliyun.AccessKeySecret</code><p>优先 CDN 专用凭据，其次租户 DNS 私密凭据，最后兼容当前租户 SaaS 中的阿里云 DNS 凭据。填写了一半的凭据会报错，不会混用其他来源。</p><p>SLS 可复用该凭据，或单独配置 <code>Integration.Cdn.Aliyun.Sls.AccessKeyId / AccessKeySecret</code>。需要 CDN 只读/管理权限及 <code>log:GetLogStoreLogs</code>；海量封禁还需要阿里云开通服务。</p><a href="https://help.aliyun.com/zh/cdn/use-cases/best-practices-for-preventing-traffic-theft" target="_blank" rel="noopener noreferrer">阿里云流量盗刷分析与防护说明</a></section>
      <section class="mci-cdn__panel"><h3>{{ domain || '请先选择域名' }} · 实时日志与保护</h3><div class="mci-cdn__form"><label>SLS 地域<input v-model="settings.SlsRegion" placeholder="cn-hangzhou"/></label><label>SLS Project<input v-model="settings.SlsProject"/></label><label>SLS Logstore<input v-model="settings.SlsLogstore"/></label><label>采集等待（秒）<input v-model.number="settings.DelaySeconds" type="number" min="60" max="3600"/></label><label>最大数据滞后（秒）<input v-model.number="settings.MaxLagSeconds" type="number" min="60" max="3600"/></label><label>每小时最多自动操作<input v-model.number="settings.MaxActionsPerHour" type="number" min="1" max="100"/></label><label class="wide">保护白名单<textarea v-model="whiteText" rows="4" placeholder="每行一个可信业务出口、监控或合作伙伴 IP / CIDR"/></label><label class="wide"><input v-model="settings.AutoEnabled" type="checkbox"/>允许此域名的“自动执行”规则封禁 IP（默认关闭）</label></div><p class="mci-cdn__hint">SLS 需建立 domain、remote_ip、uri、refer_domain、response_size、return_code 的字段索引，其中 response_size 为数值。私网、环回、链路本地和组播地址始终受保护。</p><button class="primary" :disabled="busy||!domain" @click="saveSettings">保存域名接入设置</button></section>
    </template>
    <Teleport to="body"><dialog ref="confirmDialog" class="mci-cdn mci-cdn__dialog" @cancel.prevent="closePreview" :style="{transform:`translate(${drag.x}px, ${drag.y}px)`}"><template v-if="preview"><header @pointerdown="beginDrag"><h3>确认 CDN 云端变更</h3><button aria-label="关闭确认" :disabled="submitting" @click="closePreview">×</button></header><p><b>操作：</b>{{ preview.Command.Action }}　<b>作用范围：</b>{{ preview.Scope }}</p><p class="mci-cdn__error">{{ preview.Warning }}</p><pre>{{ JSON.stringify(preview.Command,null,2) }}</pre><p>提交后新建持久化操作；同域名已有任务运行时会排队。确认有效期为 5 分钟。</p><p v-if="dialogError" role="alert" class="mci-cdn__error">{{ dialogError }}</p><footer><button :disabled="submitting" @click="closePreview">取消</button><button class="primary" :disabled="submitting" @click="submit">{{ submitting?'提交中…':'确认执行' }}</button></footer></template></dialog><div v-if="notice" class="mci-cdn mci-cdn__toast" role="status">{{ notice }}<button @click="notice=''">关闭</button></div></Teleport>
  </section>
</template>

<script setup>
import {computed,nextTick,onBeforeUnmount,onMounted,reactive,ref} from 'vue'
import {configureV8,dispatch,getContext} from '../microi'
import ObservabilityTable from './ObservabilityTable.vue'
import {parse,reportRows,reportTypes,bytes,csv,statuses} from '../cdn-model'
const tabs=[{key:'analysis',label:'流量与 TOP'},{key:'security',label:'安全处置'},{key:'rules',label:'自动规则'},{key:'settings',label:'接入与白名单'}]
const tab=ref('analysis'),capability=ref({}),domains=ref([]),domainCount=ref(0),domain=ref(''),initializing=ref(true),busy=ref(false),error=ref(''),notice=ref('')
const source=ref('report'),reportId=ref(15),dimension=ref('ip'),metric=ref('bytes'),filterIp=ref(''),area=ref(''),isOverseas=ref('0'),analysisRows=ref([]),analysisMeta=ref({}),retrievedAt=ref(''),trend=ref([])
const localTime=d=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)
const end=ref(localTime(new Date(new Date().setHours(0,0,0,0)))),start=ref(localTime(new Date(new Date().setHours(0,0,0,0)-86400000)))
const settings=reactive({SlsRegion:'',SlsProject:'',SlsLogstore:'',DelaySeconds:300,MaxLagSeconds:600,MaxActionsPerHour:10,AutoEnabled:false}),whiteText=ref('')
const securityAction=ref('Block'),ipText=ref(''),duration=ref(3600),customDuration=ref(3600),rate=ref('1m'),referers=ref(''),allowEmpty=ref(true),reason=ref(''),globalConfirm=ref(false),cloudConfigs=ref([]),operationRows=ref([]),rules=ref([])
const initialRule=()=>({Id:'',Name:'流量异常观察',Mode:'observe',Enabled:false,Metric:'bytes',ThresholdType:'fixed',Threshold:1073741824,WindowMinutes:5,BaselineWindows:7,Multiplier:3,Consecutive:2,Duration:3600,CooldownSeconds:3600,MaxIps:3})
const ruleForm=reactive(initialRule()),preview=ref(null),confirmDialog=ref(null),submitting=ref(false),dialogError=ref(''),drag=reactive({x:0,y:0});let requestKey='',lastRefresh=0,alive=true
const dataState=computed(()=>!retrievedAt.value?'待查询':source.value==='report'?(analysisRows.value.length?'历史报表':'无可用报表'):analysisMeta.value.Complete?'查询完整':'数据未完整')
const labels={ip:'IP',remote_ip:'连接 IP',client_ip:'客户端 IP',url:'资源 URL',uri:'资源路径',referer:'Referer',refer_domain:'Referer 域名',acc:'请求次数',traf:'流量（报表原始单位）',traf_rate:'流量占比',acc_rate:'请求占比',requests:'请求次数',bytes:'响应流量',return_code:'HTTP 状态',last_seen:'最后访问秒'}
const analysisColumns=computed(()=>[...[...new Set(analysisRows.value.flatMap(Object.keys))].filter(k=>!['missing_bytes','__source__'].includes(k)).slice(0,12).map(key=>({key,label:labels[key]||key})),{key:'cdnAction',label:'操作'}])
const operationColumns=[{key:'Domain',label:'域名'},{key:'Action',label:'操作'},{key:'status',label:'状态'},{key:'CreatedBy',label:'操作人'},{key:'CreateTime',label:'时间'},{key:'expiryText',label:'到期'},{key:'resultText',label:'结果'},{key:'action',label:'核实'}]
const trendPath=computed(()=>{const max=Math.max(1,...trend.value.map(x=>Number(x.Value)||0));return trend.value.map((x,i)=>`${i?'L':'M'}${i/(trend.value.length-1)*900},${130-(Number(x.Value)||0)/max*120}`).join(' ')})
async function api(Action,data={}){const v8=configureV8(),payload={Action,Provider:'aliyun',Domain:domain.value,...data};const raw=v8.Http?.Post?await v8.Http.Post({Url:'/apiengine/mci-cdn-manager',PostParam:payload}):await v8.post('/apiengine/mci-cdn-manager',payload);const r=parse(raw);if(r?.Code!==1)throw Error(r?.Msg||'CDN 请求失败');return r.Data}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){if(alive)error.value=e.message}finally{if(alive)busy.value=false}}
async function loadDomains(){await run(async()=>{const r=await api('Domains');domains.value=r.Domains?.PageData||[];domainCount.value=Number(r.TotalCount)||0;if(!domain.value)domain.value=domains.value[0]?.DomainName||'';if(domain.value)await loadSettingsData()})}
async function loadMoreDomains(){await run(async()=>{const r=await api('Domains',{Page:Math.floor(domains.value.length/50)+1});domains.value.push(...(r.Domains?.PageData||[]))})}
async function loadSettingsData(){const r=await api('Config');Object.assign(settings,r);whiteText.value=(r.Whitelist||[]).join('\n')}
async function changeDomain(){analysisRows.value=[];trend.value=[];retrievedAt.value='';await run(loadSettingsData);await selectTab(tab.value)}
async function selectTab(key){tab.value=key;if(!domain.value)return;if(key==='security'){await loadSecurity();await loadOperations()}if(key==='rules')await loadRules();if(key==='settings')await run(loadSettingsData)}
function range(){const from=new Date(start.value),to=new Date(end.value);if(!Number.isFinite(+from)||!Number.isFinite(+to)||to<=from)throw Error('请选择有效起止时间');return {StartTime:from.toISOString(),EndTime:to.toISOString(),From:Math.floor(+from/1000),To:Math.floor(+to/1000)}}
async function loadAnalysis(){await run(async()=>{const r=source.value==='report'?await api('Reports',{...range(),ReportId:reportId.value,Area:area.value,IsOverseas:isOverseas.value}):await api('Sls',{...range(),Dimension:dimension.value,Metric:metric.value,Ip:filterIp.value,Top:100});analysisMeta.value=r;analysisRows.value=source.value==='report'?reportRows(r.Content):r.Rows||[];retrievedAt.value=new Date().toLocaleString()})}
async function loadTrend(){await run(async()=>{const r=await api('Trend',{...range(),Interval:300});trend.value=r.BpsDataPerInterval?.DataModule||[]})}
async function loadSecurity(){await run(async()=>{const r=await api('Configs');cloudConfigs.value=(r.DomainConfigs?.DomainConfig||[]).map(x=>({...x,summary:(x.FunctionArgs?.FunctionArg||[]).map(a=>`${a.ArgName}: ${a.ArgValue}`).join(' · ')}))})}
async function loadOperations(){await run(async()=>{operationRows.value=(await api('Operations')).map(x=>({...x,expiryText:x.ExpireAt?new Date(x.ExpireAt*1000).toLocaleString():'—',resultText:parse(x.ResultJson).Message||parse(x.PayloadJson).Reason||''}))})}
async function loadRules(){await run(async()=>{rules.value=(await api('Rules')).map(x=>({...x,modeText:`${x.Enabled?'启用':'停用'} · ${x.Mode==='enforce'?'自动执行':'观察'}`,scanText:x.LastScan?new Date(x.LastScan*1000).toLocaleString():'未扫描',evaluation:parse(x.StateJson).LastError||JSON.stringify(parse(x.StateJson).LastEvaluation||{})}))})}
async function saveSettings(){await run(async()=>{await api('SaveConfig',{Config:{...settings,Whitelist:whiteText.value.split(/[\s,;]+/).filter(Boolean)}});notice.value='域名接入设置已保存'})}
function resetRule(){Object.assign(ruleForm,initialRule())}
function editRule(row){Object.assign(ruleForm,initialRule(),parse(row.RuleJson),{Id:row.Id,Name:row.Name,Enabled:Number(row.Enabled)===1})}
async function saveRule(){await run(async()=>{await api('SaveRule',{Id:ruleForm.Id,Name:ruleForm.Name,Enabled:ruleForm.Enabled,Rule:{...ruleForm}});notice.value='规则已保存'}) ;await loadRules()}
function analyzeIp(row){source.value='sls';dimension.value='ipUrl';filterIp.value=row.remote_ip||row.ip||row.client_ip;tab.value='analysis';void loadAnalysis()}
function stageBlock(row){ipText.value=row.remote_ip||row.ip||row.client_ip;securityAction.value='Block';tab.value='security';void loadSecurity()}
function overlay(visible){const c=getContext();dispatch('micro-app:host-action',{action:'setGlobalOverlay',requestId:`cdn-overlay-${Date.now()}`,visible,blur:!c.disableFormMaskBlur,lockScroll:visible,nativeTopLayer:true,mask:visible,promote:visible,silent:true},{force:true})}
async function prepare(Action){await run(async()=>{preview.value=await api('Preview',{Command:{Action,Provider:'aliyun',Domain:domain.value,IPList:ipText.value,Duration:duration.value===-1?customDuration.value:duration.value,Rate:rate.value,Referers:referers.value.split(/[\s,;]+/).filter(Boolean),AllowEmpty:allowEmpty.value,Reason:reason.value,ScopeConfirmation:globalConfirm.value?'ALL_CDN_DOMAINS':''}});requestKey=crypto.randomUUID();dialogError.value='';drag.x=0;drag.y=0;await nextTick();confirmDialog.value.showModal();overlay(true)})}
async function prepareRuleDelete(row){preview.value={Kind:'Rule',Id:row.Id,Command:{Action:'DeleteRule',Name:row.Name},Scope:row.Domain,Warning:'删除此规则和对应调度；已有封禁继续按原定期限回收。'};dialogError.value='';await nextTick();confirmDialog.value.showModal();overlay(true)}
function closePreview(){if(submitting.value)return;confirmDialog.value?.close();preview.value=null;overlay(false)}
async function submit(){submitting.value=true;dialogError.value='';try{if(preview.value.Kind==='Rule'){await api('DeleteRule',{Id:preview.value.Id});submitting.value=false;closePreview();notice.value='规则和独立调度已删除';tab.value='rules';resetRule();await loadRules();return}const result=await api('Submit',{...preview.value,RequestKey:requestKey});submitting.value=false;closePreview();notice.value=`${statuses[result.Status]||result.Status} · ${result.Id}`;tab.value='security';await loadOperations()}catch(e){dialogError.value=e.message}finally{submitting.value=false}}
async function reconcile(row){await run(async()=>{const r=await api('Reconcile',{Id:row.Id});notice.value=statuses[r.Status]||r.Status});await loadOperations()}
function exportRows(){const url=URL.createObjectURL(new Blob([csv(analysisRows.value)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`cdn-${domain.value}-${source.value}.csv`;a.click();URL.revokeObjectURL(url)}
function beginDrag(event){if(event.target.closest('button')||event.button!==0)return;const sx=event.clientX,sy=event.clientY,ox=drag.x,oy=drag.y;const move=e=>{drag.x=Math.max(-window.innerWidth*.35,Math.min(window.innerWidth*.35,ox+e.clientX-sx));drag.y=Math.max(-window.innerHeight*.25,Math.min(window.innerHeight*.25,oy+e.clientY-sy))};const end=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',end,{once:true})}
async function refresh(){if(Date.now()-lastRefresh<60000)return;lastRefresh=Date.now();await selectTab(tab.value)}
defineExpose({refresh})
onMounted(async()=>{try{const r=await api('Capabilities');capability.value=r.Providers?.find(x=>x.Provider==='aliyun')||{};if(capability.value.Configured)await loadDomains()}catch(e){error.value=e.message}finally{initializing.value=false}})
onBeforeUnmount(()=>{alive=false;confirmDialog.value?.close();overlay(false)})
</script>

